    public function parse(\Phplrt\Contracts\Source\ReadableInterface $source): mixed
    {
        return $this->parser->parse($source);
    }

    private static function reduceScript(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        if ($children === null) {
                return new \Inilim\SqliteParser\Ast\Script([]);
            }
            if (\is_array($children)) {
                return new \Inilim\SqliteParser\Ast\Script($children);
            }
            // Одиночный Statement (unwrap-случай) — оборачиваем в массив.
            if ($children instanceof \Inilim\SqliteParser\Ast\Statement) {
                return new \Inilim\SqliteParser\Ast\Script([$children]);
            }

            // Сюда попадаем только для одиночного `;` — это EmptyStatement.
            return new \Inilim\SqliteParser\Ast\Script(
                [new \Inilim\SqliteParser\Ast\Statement\EmptyStatement()]
            );
    }

    private static function reduceStatementList(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $flat = [];
            \array_walk_recursive($children, static function ($item) use (&$flat): void {
                if ($item instanceof \Inilim\SqliteParser\Ast\Statement) {
                    $flat[] = $item;
                }
            });

            return $flat;
    }

    private static function reduceSelectStatement(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            // ResultColumnList — объект-контейнер (не массив), значит SelectList
            // не был развёрнут unwrap-флаттенингом на уровне этого правила.
            $columns_raw = $children[0] ?? null;
            $columns = $columns_raw instanceof \Inilim\SqliteParser\Ast\Statement\ResultColumnList
                ? $columns_raw->items
                : [];

            $from_raw  = $children[1] ?? null;
            $where_raw = $children[2] ?? null;
            $order_raw = $children[3] ?? null;
            $limit_raw = $children[4] ?? null;

            $from  = $from_raw instanceof \Inilim\SqliteParser\Ast\Statement\TableReference ? $from_raw : null;
            $where = $where_raw instanceof \Inilim\SqliteParser\Ast\Expression ? $where_raw : null;
            $orderBy = $order_raw instanceof \Inilim\SqliteParser\Ast\Statement\OrderByList
                ? $order_raw->items
                : null;
            $limit = \is_array($limit_raw) && isset($limit_raw['limit']) ? $limit_raw : null;

            return new \Inilim\SqliteParser\Ast\Statement\SelectStatement(
                columns: $columns,
                from: $from,
                where: $where,
                orderBy: $orderBy,
                limit: $limit,
            );
    }

    private static function reduceSelectList(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $first = $children[0] ?? null;
            $rest  = $children[1] ?? null;

            $list = [];
            if ($first instanceof \Inilim\SqliteParser\Ast\Statement\ResultColumn) {
                $list[] = $first;
            }
            if ($rest instanceof \Inilim\SqliteParser\Ast\Statement\ResultColumnList) {
                foreach ($rest->items as $rc) {
                    $list[] = $rc;
                }
            } elseif ($rest instanceof \Inilim\SqliteParser\Ast\Statement\ResultColumn) {
                $list[] = $rest;
            }

            return new \Inilim\SqliteParser\Ast\Statement\ResultColumnList($list);
    }

    private static function reduceResultColumn(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        // Альтернатива <T_STAR> — одиночный Token.
            if ($children instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                return new \Inilim\SqliteParser\Ast\Statement\ResultColumn(
                    new \Inilim\SqliteParser\Ast\Expression\Star(),
                    null,
                );
            }

            // Альтернатива Expression() (::T_AS:: <T_IDENT>)? — массив [Expression]
            // или [Expression, Token(alias)].
            $children = \is_array($children) ? $children : [$children];
            $expression = $children[0];
            $alias = null;
            if (isset($children[1]) && $children[1] instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                $alias = $children[1]->value;
            }

            return new \Inilim\SqliteParser\Ast\Statement\ResultColumn($expression, $alias);
    }

    private static function reduceOrExpr(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
            $left = $children[0] ?? null;
            if (!$left instanceof \Inilim\SqliteParser\Ast\Expression) {
                return $left;
            }
            return \Inilim\SqliteParser\Grammar\Reducers::foldLeftBinaryChain(
                $left,
                $children[1] ?? null,
                'OR',
            );
    }

    private static function reduceAndExpr(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
            $left = $children[0] ?? null;
            if (!$left instanceof \Inilim\SqliteParser\Ast\Expression) {
                return $left;
            }
            return \Inilim\SqliteParser\Grammar\Reducers::foldLeftBinaryChain(
                $left,
                $children[1] ?? null,
                'AND',
            );
    }

    private static function reduceNotExpr(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
            if (isset($children[0]) && $children[0] instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                $operand = $children[1] ?? null;
                if ($operand instanceof \Inilim\SqliteParser\Ast\Expression) {
                    return new \Inilim\SqliteParser\Ast\Expression\UnaryOperation('NOT', $operand);
                }
            }
            return $children[0] ?? null;
    }

    private static function reduceComparison(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
            $left = $children[0] ?? null;
            if (!$left instanceof \Inilim\SqliteParser\Ast\Expression) {
                return $left;
            }
            return \Inilim\SqliteParser\Grammar\Reducers::foldLeftBinaryChain(
                $left,
                $children[1] ?? null,
            );
    }

    private static function reduceAdditive(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
            $left = $children[0] ?? null;
            if (!$left instanceof \Inilim\SqliteParser\Ast\Expression) {
                return $left;
            }
            return \Inilim\SqliteParser\Grammar\Reducers::foldLeftBinaryChain(
                $left,
                $children[1] ?? null,
            );
    }

    private static function reduceMultiplicative(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];
            $left = $children[0] ?? null;
            if (!$left instanceof \Inilim\SqliteParser\Ast\Expression) {
                return $left;
            }
            return \Inilim\SqliteParser\Grammar\Reducers::foldLeftBinaryChain(
                $left,
